"""Reworked Editor environment, audio and shaded material symbols."""
def register_editor_surface_icons(icon):
    defs='''<linearGradient id="editor-hdri-horizon" x2="0" y2="1"><stop stop-color="#3882c4"/><stop offset=".49" stop-color="#99d5ed"/><stop offset=".62" stop-color="#ffdda0"/><stop offset=".65" stop-color="#497f88"/><stop offset="1" stop-color="#254d65"/></linearGradient><linearGradient id="editor-hdri-zenith" x2=".7" y2="1"><stop stop-color="#22599d"/><stop offset="1" stop-color="#81c8e7"/></linearGradient><linearGradient id="editor-hdri-ground" x2="0" y2="1"><stop stop-color="#51828c"/><stop offset="1" stop-color="#213e55"/></linearGradient>'''
    body='<g stroke="#a4c6d9" stroke-width="1.8" stroke-linejoin="round">'
    for x in [32,80,128,176]:body+=f'<rect x="{x}" y="99" width="44" height="44" rx="3" fill="url(#editor-hdri-horizon)"/>'
    body+='''<rect x="80" y="51" width="44" height="44" rx="3" fill="url(#editor-hdri-zenith)"/><rect x="80" y="147" width="44" height="44" rx="3" fill="url(#editor-hdri-ground)"/></g><circle cx="103" cy="112" r="7" fill="#fff4c8"/><path d="M49 161q4 35 26 39m-8-12 8 12-15 1M183 80q-4-22-30-26m11 12-11-12 15-1" stroke="#8dcced" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/>'''
    icon('editor-hdri-light','HDRI light','Editor','An unfolded six-face environment map with a continuous sky/ground horizon, a bright light source and wraparound arrows. No chrome probe or panorama frame.',defs,body)

    body='''<rect x="33" y="64" width="190" height="137" rx="16" fill="#e9e5de"/><path d="M43 185h169" stroke="#cbc8c1" stroke-width="2"/><circle cx="102" cy="128" r="55" fill="#aeb3b3"/><circle cx="102" cy="128" r="51" fill="#20262c"/><path d="M64 113a41 41 0 0 1 53-24m21 55a40 40 0 0 1-52 22" stroke="#626b71" stroke-width="1.6" fill="none"/><path d="M68 107a39 39 0 0 1 38-18m27 58a36 36 0 0 1-36 15" stroke="#454f57" stroke-width="1.2" fill="none"/><circle cx="102" cy="128" r="20" fill="#ef695d"/><circle cx="102" cy="128" r="3.5" fill="#ffe0c3"/><circle cx="188" cy="89" r="12" fill="#a8b1b4"/><path d="m188 89-7 45-29 19" stroke="#56636c" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><path d="m188 89-7 45-29 19" stroke="#f9faf5" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="m155 150-10 6" stroke="#86999f" stroke-width="9" stroke-linecap="round"/><circle cx="188" cy="89" r="7" fill="#fcfcf5"/><rect x="183" y="161" width="19" height="11" rx="3" fill="#e36d62"/><circle cx="173" cy="167" r="3.5" fill="#36af83"/>'''
    icon('editor-audio-source','Audio source','Editor','A wide ivory turntable with offset vinyl platter, coral center label, independent right-side tonearm and separate transport controls. Flat SVG, no app-icon tile or heavy concentric rings.','',body)

    defs='''<radialGradient id="editor-material-volume" cx="30%" cy="24%" r="83%"><stop stop-color="#edf5ff"/><stop offset=".2" stop-color="#b8cee5"/><stop offset=".44" stop-color="#839dc4"/><stop offset=".7" stop-color="#455a87"/><stop offset=".89" stop-color="#222f50"/><stop offset="1" stop-color="#617d9e"/></radialGradient><radialGradient id="editor-material-specular" cx="32%" cy="23%" r="51%"><stop stop-color="#ffffff" stop-opacity=".95"/><stop offset=".26" stop-color="#f2faff" stop-opacity=".5"/><stop offset=".66" stop-color="#e7f2ff" stop-opacity=".1"/><stop offset="1" stop-color="#d2e7ff" stop-opacity="0"/></radialGradient><linearGradient id="editor-material-rim" x2=".7" y2="1"><stop stop-color="#eaf7ff" stop-opacity=".85"/><stop offset=".5" stop-color="#9acbff" stop-opacity=".1"/><stop offset="1" stop-color="#c5d9f3" stop-opacity=".55"/></linearGradient><clipPath id="editor-material-ball"><circle cx="128" cy="128" r="77"/></clipPath>'''
    body='''<circle cx="128" cy="128" r="77" fill="url(#editor-material-volume)"/><g clip-path="url(#editor-material-ball)"><circle cx="128" cy="128" r="77" fill="url(#editor-material-specular)"/><path d="M68 77c-6 61 63 109 133 74" stroke="#101f3d" stroke-opacity=".55" stroke-width="3" fill="none"/><path d="M67 80c-5 61 64 109 133 74" stroke="#d2e3f4" stroke-opacity=".45" stroke-width="1.1" fill="none"/><path d="M76 101q12-30 42-36" stroke="#ffffff" stroke-opacity=".2" stroke-width="4" stroke-linecap="round" fill="none"/></g><circle cx="128" cy="128" r="77" stroke="url(#editor-material-rim)" stroke-width="1"/>'''
    icon('editor-material','Material','Editor','A volumetric satin shader ball: curved studio reflections, a recessed surface seam, deep falloff and a cool reflected edge. Native SVG gradients, not a flat filled disc.',defs,body)
